def countThreeLetterPalindromes(s):
    first = {}
    last = {}
    for i, c in enumerate(s):
        if c not in first:
            first[c] = i
        last[c] = i
    total = 0
    for c in first:
        if last[c] - first[c] >= 2:
            total += len(set(s[first[c] + 1:last[c]]))
    return total
